const config = {
  "previewFeatures": [
    "driverAdapters"
  ],
  "clientVersion": "7.4.2",
  "engineVersion": "94a226be1cf2967af2541cca5529f0f7ba866919",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../lib/generated/prisma\"\n  previewFeatures = [\"driverAdapters\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ─── Tenant (Law Firm) ───────────────────────────────────────────────────────\n\nmodel Organization {\n  id        String   @id @default(cuid())\n  name      String\n  slug      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  users           User[]\n  orgContacts     OrgContact[]\n  retentionPolicy RetentionPolicy?\n  legalHolds      LegalHold[]\n\n  @@map(\"organizations\")\n}\n\n// ─── Data Retention Policy ───────────────────────────────────────────────────\n// Per-org cached-data retention. A value of 0 means \"keep forever\" (the safe\n// default). The retention cron purges cached items older than the window —\n// but NEVER purges data covered by an active LegalHold.\n\nmodel RetentionPolicy {\n  id    String       @id @default(cuid())\n  orgId String       @unique\n  org   Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)\n\n  // Days to retain each cached data class. 0 = keep forever (default).\n  cachedEmailDays    Int @default(0)\n  cachedCalendarDays Int @default(0)\n  cachedContactDays  Int @default(0)\n  auditLogDays       Int @default(0) // audit logs are usually kept long; 0 = forever\n\n  updatedAt DateTime @updatedAt\n  createdAt DateTime @default(now())\n\n  @@map(\"retention_policies\")\n}\n\n// ─── Legal Hold ──────────────────────────────────────────────────────────────\n// Litigation hold: while active, the covered scope is EXEMPT from retention\n// purging. Scope is either an entire org (userId = null) or a single user.\n// Holds are never auto-deleted; releasing sets releasedAt (kept for the record).\n\nmodel LegalHold {\n  id     String       @id @default(cuid())\n  orgId  String\n  org    Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)\n  userId String? // null = whole-org hold; set = single-user hold\n\n  reason          String\n  createdByUserId String\n  createdAt       DateTime  @default(now())\n  releasedAt      DateTime? // null = active\n\n  @@index([orgId, releasedAt])\n  @@index([userId, releasedAt])\n  @@map(\"legal_holds\")\n}\n\n// ─── Organization Directory Contacts ─────────────────────────────────────────\n// Shared contact list visible to all users in the org.\n// Imported from CSV or managed by admins. Read-only for regular users.\n\nmodel OrgContact {\n  id    String       @id @default(cuid())\n  orgId String\n  org   Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)\n\n  firstName String\n  lastName  String\n  email     String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([orgId, email])\n  @@index([orgId])\n  @@map(\"org_contacts\")\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id        String   @id // matches Supabase auth.users.id\n  email     String   @unique\n  name      String?\n  avatarUrl String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orgId String\n  org   Organization @relation(fields: [orgId], references: [id])\n\n  // RBAC role within the org. \"member\" (default) | \"org_admin\" | \"super_admin\".\n  // super_admin is bootstrapped from the ADMIN_EMAILS allowlist; org_admin is\n  // granted by a super_admin / existing org_admin and is scoped to its own org.\n  role String @default(\"member\")\n\n  // Notification preferences\n  notificationNewEmail          Boolean @default(true)\n  notificationDailyDigest       Boolean @default(false)\n  notificationAiReplies         Boolean @default(true)\n  notificationCalendarReminders Boolean @default(true)\n  notificationWeeklyReport      Boolean @default(false)\n\n  // Appearance preferences\n  appTheme     String @default(\"light\") // light | dark\n  fontSize     String @default(\"default\") // default | compact | comfortable\n  emailDensity String @default(\"comfortable\") // comfortable | compact\n\n  // Timezone preference\n  preferredTimeZone String @default(\"America/Chicago\")\n\n  // Multi-account preference\n  lastActiveAccountId String?\n\n  // Undo Send preference (delay in seconds before email actually sends)\n  undoSendDelay Int @default(10) // 5 | 10 | 20 | 30\n\n  // Default sensitivity label applied to new emails\n  // none | attorney-client | confidential | work-product (null = none)\n  defaultSensitivityLabel String?\n\n  // AI voice profile — cached analysis of user's writing style\n  voiceProfile          Json?\n  voiceProfileUpdatedAt DateTime?\n\n  msAccounts          MsConnectedAccount[]\n  imapAccounts        ImapConnectedAccount[]\n  jmapAccounts        JmapConnectedAccount[]\n  msalCache           MsalTokenCache?\n  deltaLinks          EmailDeltaLink[]\n  webhookSubs         WebhookSubscription[]\n  drafts              Draft[]\n  emailRules          EmailRule[]\n  signatures          Signature[]\n  emailTemplates      EmailTemplate[]\n  cachedFolders       CachedFolder[]\n  cachedEmails        CachedEmail[]\n  cachedCalEvents     CachedCalendarEvent[]\n  cachedContacts      CachedContact[]\n  emailAttachments    EmailAttachment[]\n  aiGeneratedReplies  AiGeneratedReply[]\n  cachedSearchResults CachedSearchResult[]\n  syncStatuses        SyncStatus[]\n  notificationLogs    NotificationLog[]\n  migrationStatuses   MigrationStatus[]\n  todoItems           TodoItem[]\n  snoozedEmails       SnoozedEmail[]\n  readReceipts        ReadReceipt[]\n  pendingEmails       PendingEmail[]\n  followUpReminders   FollowUpReminder[]\n  aiEmailInsights     AiEmailInsight[]\n\n  @@map(\"users\")\n}\n\n// ─── Microsoft Connected Accounts ────────────────────────────────────────────\n\nmodel MsConnectedAccount {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  homeAccountId String\n  msEmail       String\n  displayName   String?\n  tenantId      String?\n  isDefault     Boolean  @default(false)\n  connectedAt   DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, homeAccountId])\n  @@map(\"ms_connected_accounts\")\n}\n\n// ─── MSAL Token Cache ─────────────────────────────────────────────────────────\n\nmodel MsalTokenCache {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  cacheJson String   @db.Text\n  updatedAt DateTime @updatedAt\n\n  @@map(\"msal_token_cache\")\n}\n\n// ─── Email Delta Links ────────────────────────────────────────────────────────\n\nmodel EmailDeltaLink {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String\n  folderId      String\n  deltaToken    String   @db.Text\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, homeAccountId, folderId])\n  @@map(\"email_delta_links\")\n}\n\n// ─── Webhook Subscriptions ────────────────────────────────────────────────────\n\nmodel WebhookSubscription {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId  String\n  subscriptionId String   @unique\n  resource       String\n  expiresAt      DateTime\n  clientState    String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@map(\"webhook_subscriptions\")\n}\n\n// ─── Drafts ───────────────────────────────────────────────────────────────────\n\nmodel Draft {\n  id            String  @id @default(cuid())\n  userId        String\n  user          User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String?\n  graphDraftId  String? // MS Graph message ID — set when draft synced to Outlook\n  toRecipients  Json    @default(\"[]\")\n  ccRecipients  Json    @default(\"[]\")\n  bccRecipients Json    @default(\"[]\")\n  subject       String?\n  bodyHtml      String? @db.Text\n  attachments   Json    @default(\"[]\")\n\n  // Message settings\n  importance             String  @default(\"normal\") // normal | high | low\n  sensitivity            String  @default(\"normal\") // normal | personal | private | confidential\n  requestReadReceipt     Boolean @default(false)\n  requestDeliveryReceipt Boolean @default(false)\n  categories             Json    @default(\"[]\")\n\n  // Reply/forward context\n  draftType           String  @default(\"new\") // new | reply | forward\n  inReplyToMessageId  String? // Original message ID for replies\n  forwardedMessageId  String? // Original message ID for forwards\n  originalMessageBody String? @db.Text // For preserving context\n\n  // Scheduled send\n  scheduledAt               DateTime? // null = send immediately; set = scheduled send\n  scheduledSent             Boolean   @default(false)\n  scheduledNotificationSent Boolean   @default(false)\n  lastScheduleAttemptAt     DateTime?\n  scheduleAttemptCount      Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, updatedAt(sort: Desc)])\n  @@index([scheduledAt, scheduledSent])\n  @@map(\"drafts\")\n}\n\n// ─── Signatures ───────────────────────────────────────────────────────────────\n\nmodel Signature {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name           String\n  html           String   @default(\"\") @db.Text // Rich HTML signature body\n  title          String?\n  company        String?\n  phone          String?\n  defaultNew     Boolean  @default(false) // Use for new emails\n  defaultReplies Boolean  @default(false) // Use for replies/forwards\n  account        String   @default(\"all\") // Account scope: \"all\" or specific email\n  isDefault      Boolean  @default(false)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@map(\"signatures\")\n}\n\n// ─── Sync Cache ───────────────────────────────────────────────────────────────\n\nmodel CachedFolder {\n  id             String   @id\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId  String\n  displayName    String\n  parentFolderId String?\n  unreadCount    Int      @default(0)\n  totalCount     Int      @default(0)\n  wellKnownName  String?\n  syncedAt       DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([userId, homeAccountId, wellKnownName])\n  @@map(\"cached_folders\")\n}\n\nmodel CachedEmail {\n  id               String    @id\n  userId           String\n  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId    String\n  folderId         String\n  subject          String    @default(\"\")\n  bodyPreview      String    @default(\"\") @db.Text\n  fromName         String    @default(\"\")\n  fromAddress      String    @default(\"\")\n  toRecipients     Json      @default(\"[]\")\n  receivedDateTime DateTime\n  sentDateTime     DateTime?\n  isRead           Boolean   @default(false)\n  hasAttachments   Boolean   @default(false)\n  flagStatus       String    @default(\"notFlagged\")\n  categories       Json      @default(\"[]\")\n\n  // Additional metadata\n  importance              String    @default(\"normal\") // normal | high | low\n  sensitivity             String    @default(\"normal\") // normal | personal | private | confidential\n  inferenceClassification String    @default(\"other\") // focused | other\n  conversationId          String?\n  isDraft                 Boolean   @default(false)\n  syncStatus              String    @default(\"synced\")\n  lastModifiedDateTime    DateTime?\n\n  // Sensitivity / Privilege label\n  sensitivityLabel String? // \"attorney-client-privilege\" | \"confidential\" | \"work-product\" | null\n\n  // Pinned emails\n  isPinned Boolean @default(false)\n\n  syncedAt  DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, homeAccountId, folderId, receivedDateTime(sort: Desc)])\n  @@index([userId, homeAccountId, isRead])\n  @@index([userId, homeAccountId, flagStatus])\n  @@index([userId, homeAccountId, isPinned])\n  @@index([userId, conversationId])\n  @@map(\"cached_emails\")\n}\n\nmodel CachedCalendarEvent {\n  id               String   @id\n  userId           String\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId    String\n  subject          String   @default(\"\")\n  bodyPreview      String   @default(\"\") @db.Text\n  bodyHtml         String?  @db.Text\n  startDateTime    DateTime\n  endDateTime      DateTime\n  isAllDay         Boolean  @default(false)\n  location         String?\n  organizerName    String?\n  organizerEmail   String?\n  organizerType    String   @default(\"required\") // required | optional\n  responseStatus   String   @default(\"none\")\n  onlineMeetingUrl String?\n  attendees        Json     @default(\"[]\")\n  isRecurring      Boolean  @default(false)\n\n  // Event settings\n  reminderMinutes Int? // Reminder time in minutes (null = no reminder)\n  showAs          String  @default(\"busy\") // busy | free | tentative\n  recurrence      String? // daily | weekly | monthly | null\n  eventColor      String?\n  timeZone        String  @default(\"UTC\")\n\n  // Teams meeting data\n  teamsMeetingUrl String?\n  teamsMeetingId  String?\n\n  // Recurrence tracking\n  seriesMasterId String?\n  iCalUId        String?\n  calendarId     String?\n\n  // Timestamps\n  createdDateTime      DateTime?\n  lastModifiedDateTime DateTime?\n  syncedAt             DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  @@index([userId, startDateTime, endDateTime])\n  @@map(\"cached_calendar_events\")\n}\n\nmodel CachedContact {\n  id            String @id\n  userId        String\n  user          User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String\n  displayName   String @default(\"\")\n  emailAddress  String @default(\"\") // Legacy - use emailAddresses array\n  phone         String @default(\"\") // Legacy - use phones array\n  jobTitle      String @default(\"\")\n  company       String @default(\"\")\n  department    String @default(\"\")\n\n  // Structured contact data\n  emailAddresses Json   @default(\"[]\") // Array of {address, name}\n  phones         Json   @default(\"[]\") // Array of {type, value}\n  givenName      String @default(\"\")\n  surname        String @default(\"\")\n  middleName     String @default(\"\")\n  addresses      Json   @default(\"[]\") // Structured addresses\n  imAddresses    Json   @default(\"[]\") // IM handles\n\n  // CRM features\n  categories     Json      @default(\"[]\") // Tags/labels\n  notes          String    @default(\"\")\n  birthday       DateTime?\n  anniversary    DateTime?\n  manager        String?\n  directReports  Json      @default(\"[]\")\n  frequencyScore Int       @default(0)\n  isVIP          Boolean   @default(false)\n  isFavorite     Boolean   @default(false)\n\n  syncedAt  DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, homeAccountId, displayName])\n  @@map(\"cached_contacts\")\n}\n\n// ─── Deploy Log ───────────────────────────────────────────────────────────────\n\nmodel DeployLog {\n  id           String    @id @default(cuid())\n  pusher       String\n  commits      Json // string[] of commit messages\n  createdAt    DateTime  @default(now())\n  digestSentAt DateTime?\n  updatedAt    DateTime  @updatedAt\n\n  @@index([digestSentAt, createdAt])\n  @@map(\"deploy_log\")\n}\n\n// ─── Email Rules ──────────────────────────────────────────────────────────────\n\nmodel EmailRule {\n  id             String  @id @default(cuid())\n  userId         String\n  user           User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name           String\n  priority       Int\n  active         Boolean @default(true)\n  conditions     Json\n  actions        Json\n  emailCount     Int     @default(0)\n  stopProcessing Boolean @default(false)\n\n  // Execution tracking\n  lastExecutedAt      DateTime?\n  lastExecutionStatus String?\n  lastExecutionError  String?\n  failureCount        Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, priority])\n  @@map(\"email_rules\")\n}\n\n// ─── Rule Execution Log (idempotency) ────────────────────────────────────────\n// One row per (rule, email) the server engine has acted on, so a rule never\n// re-fires on the same message across sync runs.\n\nmodel RuleExecution {\n  id        String   @id @default(cuid())\n  ruleId    String\n  emailId   String\n  userId    String\n  createdAt DateTime @default(now())\n\n  @@unique([ruleId, emailId])\n  @@index([userId, createdAt])\n  @@map(\"rule_executions\")\n}\n\n// ─── Email Attachments ────────────────────────────────────────────────────────\n\nmodel EmailAttachment {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messageId      String\n  graphMessageId String?\n  fileName       String\n  contentType    String\n  size           Int\n  contentHash    String?\n  isInline       Boolean  @default(false)\n  contentId      String?\n  uploadedAt     DateTime @default(now())\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([userId, messageId])\n  @@index([graphMessageId])\n  @@map(\"email_attachments\")\n}\n\n// ─── AI Generated Replies ─────────────────────────────────────────────────────\n\nmodel AiGeneratedReply {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messageId     String\n  generatedBody String   @db.Text\n  createdAt     DateTime @default(now())\n  expiresAt     DateTime\n  updatedAt     DateTime @updatedAt\n\n  @@index([userId, messageId])\n  @@index([expiresAt])\n  @@map(\"ai_generated_replies\")\n}\n\n// ─── Search Cache ─────────────────────────────────────────────────────────────\n\nmodel CachedSearchResult {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String\n  query         String\n  results       Json\n  createdAt     DateTime @default(now())\n  expiresAt     DateTime\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, homeAccountId, query])\n  @@index([expiresAt])\n  @@map(\"cached_search_results\")\n}\n\n// ─── Sync Status ──────────────────────────────────────────────────────────────\n\nmodel SyncStatus {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String\n  resourceType  String\n  lastSyncedAt  DateTime @default(now())\n  status        String   @default(\"success\")\n  errorMessage  String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, homeAccountId, resourceType])\n  @@index([lastSyncedAt])\n  @@map(\"sync_status\")\n}\n\n// ─── Notification Log ─────────────────────────────────────────────────────────\n\nmodel NotificationLog {\n  id           String   @id @default(cuid())\n  userId       String\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  type         String\n  sentAt       DateTime @default(now())\n  status       String\n  errorMessage String?\n  metadata     Json     @default(\"{}\")\n  updatedAt    DateTime @updatedAt\n\n  @@index([userId, type])\n  @@index([sentAt])\n  @@map(\"notification_log\")\n}\n\n// ─── Migration Status ─────────────────────────────────────────────────────────\n\nmodel MigrationStatus {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  migrationType String\n  completedAt   DateTime @default(now())\n  metadata      Json     @default(\"{}\")\n  updatedAt     DateTime @updatedAt\n\n  @@unique([userId, migrationType])\n  @@map(\"migration_status\")\n}\n\n// ─── Snoozed Emails ──────────────────────────────────────────────────────────\n\nmodel SnoozedEmail {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  homeAccountId String\n  messageId     String\n  snoozeUntil   DateTime\n  subject       String\n  senderName    String?\n  senderEmail   String\n  isReturned    Boolean  @default(false)\n  createdAt     DateTime @default(now())\n\n  @@index([userId, snoozeUntil, isReturned])\n  @@map(\"snoozed_emails\")\n}\n\n// ─── Read Receipts ────────────────────────────────────────────────────────────\n\nmodel ReadReceipt {\n  id             String    @id @default(cuid())\n  userId         String\n  user           User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messageId      String\n  recipientEmail String\n  deliveredAt    DateTime?\n  readAt         DateTime?\n  createdAt      DateTime  @default(now())\n\n  @@unique([messageId, recipientEmail])\n  @@index([userId, messageId])\n  @@map(\"read_receipts\")\n}\n\n// ─── Todo Items ───────────────────────────────────────────────────────────────\n\nmodel TodoItem {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  text      String\n  done      Boolean  @default(false)\n  priority  String   @default(\"normal\") // high | normal\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, createdAt(sort: Desc)])\n  @@map(\"todo_items\")\n}\n\n// ─── Email Templates ──────────────────────────────────────────────────────────\n\nmodel EmailTemplate {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name      String\n  subject   String?\n  body      String   @db.Text\n  variables Json     @default(\"[]\") // array of variable names e.g. [\"clientName\", \"matterNumber\"]\n  category  String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, category])\n  @@map(\"email_templates\")\n}\n\n// ─── Follow-Up Reminders ─────────────────────────────────────────────────────\n\nmodel FollowUpReminder {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messageId      String\n  conversationId String?\n  homeAccountId  String?\n  subject        String\n  recipient      String\n  remindAt       DateTime\n  status         String   @default(\"pending\") // pending | triggered | replied | dismissed\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([userId, status, remindAt])\n  @@map(\"follow_up_reminders\")\n}\n\n// ─── IMAP Connected Accounts ─────────────────────────────────────────────────\n\nmodel ImapConnectedAccount {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  accountId   String // \"imap:<cuid>\" — used as homeAccountId throughout the app\n  email       String\n  displayName String?\n  isDefault   Boolean  @default(false)\n  connectedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // IMAP connection settings\n  imapHost     String\n  imapPort     Int    @default(993)\n  imapSecurity String @default(\"tls\") // tls | starttls | none\n\n  // SMTP connection settings\n  smtpHost     String\n  smtpPort     Int    @default(587)\n  smtpSecurity String @default(\"starttls\") // tls | starttls | none\n\n  // Encrypted credentials (AES-256-GCM)\n  encryptedPassword String @db.Text\n  encryptionIv      String\n  encryptionTag     String\n\n  // IMAP sync state\n  uidValidity   Json @default(\"{}\") // { [folderPath]: number }\n  highestModSeq Json @default(\"{}\") // { [folderPath]: string }\n\n  @@unique([userId, accountId])\n  @@unique([userId, email])\n  @@map(\"imap_connected_accounts\")\n}\n\n// ─── JMAP Connected Accounts ─────────────────────────────────────────────────\n\nmodel JmapConnectedAccount {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  accountId   String // \"jmap:<cuid>\" — used as homeAccountId throughout the app\n  email       String\n  displayName String?\n  isDefault   Boolean  @default(false)\n  connectedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // JMAP connection settings\n  sessionUrl    String // e.g. https://api.fastmail.com/jmap/session\n  jmapAccountId String // the JMAP accountId from session response\n\n  // Encrypted credentials (AES-256-GCM) — stores API token or password\n  encryptedToken String @db.Text\n  encryptionIv   String\n  encryptionTag  String\n\n  // JMAP sync state\n  emailState   String? // JMAP state string for Email type\n  mailboxState String? // JMAP state string for Mailbox type\n\n  @@unique([userId, accountId])\n  @@unique([userId, email])\n  @@map(\"jmap_connected_accounts\")\n}\n\n// ─── Pending Emails (Undo Send) ──────────────────────────────────────────────\n\nmodel PendingEmail {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  payload   Json // Full send payload (to, cc, bcc, subject, body, attachments, etc.)\n  sendAt    DateTime // When the email should actually be sent\n  cancelled Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([userId, sendAt, cancelled])\n  @@map(\"pending_emails\")\n}\n\n// ─── AI Email Insights (per-email summary cache) ─────────────────────────────\n// Cached AI summary + action items for a message. Keyed by (userId, messageId);\n// invalidated by comparing latestReceivedAt so a new reply in the thread\n// regenerates. Generated lazily on open, never at sync time, to control spend.\n\nmodel AiEmailInsight {\n  id               String   @id @default(cuid())\n  userId           String\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messageId        String // Graph/provider message id\n  homeAccountId    String?\n  latestReceivedAt DateTime // newest message time the insight was generated against\n\n  tldr            String  @db.Text\n  bullets         Json    @default(\"[]\") // string[]\n  actionItems     Json    @default(\"[]\") // { type, label, payload }[]\n  suggestedAction String? // reply | reply_all | forward | schedule | archive | snooze | none\n\n  model     String // which model produced it\n  createdAt DateTime @default(now())\n\n  @@unique([userId, messageId])\n  @@index([userId, createdAt(sort: Desc)])\n  @@map(\"ai_email_insights\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n// Append-only record of security- and compliance-relevant actions (who did\n// what, when, from where). Required for a legal/enterprise product. Never\n// updated or deleted by application code; retained per the org's policy.\n\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  userId     String? // null for unauthenticated/system events\n  orgId      String? // tenant, when known — enables per-org audit export\n  actorEmail String? // denormalized for readability even if the user is later removed\n  action     String // e.g. \"email.send\", \"account.disconnect\", \"auth.signin\"\n  target     String? // affected entity id (messageId, accountId, ruleId, …)\n  metadata   Json? // small, non-sensitive context (never email bodies/credentials)\n  ip         String?\n  userAgent  String?\n  createdAt  DateTime @default(now())\n\n  @@index([userId, createdAt(sort: Desc)])\n  @@index([orgId, createdAt(sort: Desc)])\n  @@index([action, createdAt(sort: Desc)])\n  @@map(\"audit_logs\")\n}\n"
}

